    code: { lang: "c", src: `#include <stdint.h>
#include "stm32f4xx.h"                         /* CMSIS device header */
#define APP_BASE 0x08010000UL

typedef void (*entry_t)(void);

void jump_to_app(void) {
    const uint32_t *vt = (const uint32_t *)APP_BASE;
    uint32_t sp = vt[0], reset = vt[1];
    if ((sp & 0x2FF00000UL) != 0x20000000UL) return;   /* sanity check: SP in SRAM */
    __disable_irq();
    SysTick->CTRL = 0;                                  /* stop what the bootloader started */
    for (int i = 0; i < 8; i++) { NVIC->ICER[i] = 0xFFFFFFFFUL; NVIC->ICPR[i] = 0xFFFFFFFFUL; }
    SCB->VTOR = APP_BASE;                               /* application's vector table */
    __set_MSP(sp);
    __DSB(); __ISB();
    __enable_irq();                                     /* the app re-enables what it needs */
    ((entry_t)reset)();                                 /* never returns */
}`, note: "Check the SRAM range and slot address for your MCU; production bootloaders also verify the image before jumping." },
